-- Seed 18 SSAIR engineering services
INSERT OR IGNORE INTO "Service" ("id", "slug", "title", "shortDescription", "fullDescription", "icon", "category", "features", "technologies", "isActive", "createdAt", "updatedAt") VALUES (1, 'embedded-ai-iot', 'Embedded AI & IoT', 'Intelligent edge compute architectures with real-time sensor processing and low-power IoT telemetry.', 'We architect and manufacture end-to-end embedded artificial intelligence solutions integrated into hardened IoT networks. Combining ultra-low-power microcontrollers (ARM Cortex-M/R, ESP32, RISC-V) with quantized neural inference models (TensorFlow Lite Micro, ONNX Runtime), our devices process high-bandwidth sensor data at microsecond latencies without relying on persistent cloud connectivity.', 'ai-software', 'AI & Software', '["Edge Neural Acceleration (NPU/DSP)","Sub-Milliwatt Deep Sleep Telemetry","Industrial Modbus, CAN Bus & MQTT/SN","Hardware Cryptographic Secure Boot & TPM","Over-The-Air (OTA) Encrypted Firmware Deployment","Real-Time Operating System (FreeRTOS/Zephyr) Kernels"]', '["C/C++","FreeRTOS","ARM Cortex","ESP-IDF","TensorFlow Lite","MQTT","Edge Impulse"]', 1, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT OR IGNORE INTO "Service" ("id", "slug", "title", "shortDescription", "fullDescription", "icon", "category", "features", "technologies", "isActive", "createdAt", "updatedAt") VALUES (2, 'full-stack-development', 'Full Stack Development', 'Mission-critical web, cloud microservices, interactive 3D interfaces, and high-concurrency systems.', 'Our full stack engineering unit produces production-grade distributed software systems designed for high uptime, low-latency client synchronization, and military-grade data compliance. From reactive command-and-control operations dashboards to secure client portals, our stacks guarantee lightning performance across mobile and desktop.', 'ai-software', 'AI & Software', '["Next.js 14+ App Router Server Components","Type-Safe Distributed Microservices (gRPC, tRPC)","High-Throughput WebSocket / WebRTC Streaming","Relational & Vector Data Modeling (PostgreSQL, SQLite, pgvector)","Ultra-Smooth GPU Accelerated Visualizations (Three.js)","Automated Dockerized CI/CD Deployment Pipelines"]', '["Next.js","React","TypeScript","Node.js","Prisma ORM","Tailwind CSS","Docker"]', 1, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT OR IGNORE INTO "Service" ("id", "slug", "title", "shortDescription", "fullDescription", "icon", "category", "features", "technologies", "isActive", "createdAt", "updatedAt") VALUES (3, 'ai-data-science', 'AI Data Science', 'Deep predictive analytics, automated feature engineering, and neural time-series decision models.', 'Combining statistical signal processing with frontier deep learning, our AI data science team designs predictive pipelines that discover subtle operational patterns before human operators can perceive them. We specialize in failure mode prediction for industrial plants, automated financial forecasting, and multi-modal intelligence.', 'ai-software', 'AI & Software', '["Predictive Anomaly Detection in Multichannel Streams","Transformers for Complex Sequence Modeling","Automated Feature Stores & MLOps Pipelines","Probabilistic Forecasting with Uncertainty Quantification","Interpretable & Explainable AI (SHAP / Integrated Gradients)","Big Data Distributed Clusters (Spark / Ray)"]', '["Python","PyTorch","TensorFlow","Apache Spark","Pandas","Scikit-learn","Ray"]', 1, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT OR IGNORE INTO "Service" ("id", "slug", "title", "shortDescription", "fullDescription", "icon", "category", "features", "technologies", "isActive", "createdAt", "updatedAt") VALUES (4, 'ai-computer-vision', 'AI Computer Vision', 'Real-time multi-target tracking, YOLOv8/v10 inference, thermal imaging fusion, and sub-10ms classification.', 'Originating from deep defense R&D at CAIR DRDO, our computer vision systems achieve exceptional precision in adverse visual environments including zero-lux night vision, fog, rain, and dynamic camouflage. We deploy custom fine-tuned YOLO detection backbones, OpenCV DNN pipelines, and visual odometry algorithms directly to edge CUDA chips.', 'ai-software', 'AI & Software', '["YOLOv8/v10 Custom Neural Bounding & Pose Estimation","Multi-Sensor Optical & Long-Wave Infrared (LWIR) Fusion","Sub-10ms Multi-Class Inference on TensorRT / Jetson","Real-Time Visual Odometry & 3D Spatial SLAM","Autonomous Target Recognition (ATR) in Cluttered Scenes","High-Speed Industrial Surface Defect Inspection"]', '["OpenCV","YOLOv8","TensorRT","CUDA","Python","C++","PyTorch"]', 1, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT OR IGNORE INTO "Service" ("id", "slug", "title", "shortDescription", "fullDescription", "icon", "category", "features", "technologies", "isActive", "createdAt", "updatedAt") VALUES (5, 'cloud-devops', 'Cloud & DevOps', 'Air-gapped Kubernetes clusters, automated zero-downtime gitops, and hardened cloud infrastructure.', 'We architect and maintain defense-grade hybrid and multi-cloud environments capable of operating seamlessly across air-gapped on-premises data centers and hyper-scale public clouds (AWS, GCP, Azure). Our pipelines enforce zero-trust security postures, automated CIS benchmark compliance, and self-healing container topologies.', 'ai-software', 'AI & Software', '["Bare-Metal & Sovereign Air-Gapped Kubernetes (K8s)","Declarative GitOps with ArgoCD & Flux","Infrastructure as Code (Terraform, OpenTofu, Ansible)","Continuous Security Scanning (SAST/DAST/SBOM)","Distributed Prometheus & Grafana Distributed Observability","High-Availability Fault-Tolerant Multi-Region Failover"]', '["Kubernetes","Docker","Terraform","AWS","GCP","ArgoCD","Prometheus"]', 1, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT OR IGNORE INTO "Service" ("id", "slug", "title", "shortDescription", "fullDescription", "icon", "category", "features", "technologies", "isActive", "createdAt", "updatedAt") VALUES (6, 'modern-missile-technology', 'Modern Missile Technology', 'Advanced guidance algorithms, trajectory optimization, hardware-in-the-loop (HIL) simulation, and terminal homing.', 'Backed by foundational research conducted at premier defense laboratories, our missile technology division specializes in non-linear proportional navigation, terminal pursuit-evasion algorithms, lateral and longitudinal autopilot loops, and 6-DOF aerodynamic modeling. We validate sub-meter terminal accuracy using custom real-time Hardware-In-The-Loop (HIL) simulators.', 'defence-aerospace', 'Defence & Aerospace', '["6-Degree-of-Freedom (6-DOF) Aerodynamic Flight Simulation","Proportional Navigation & Non-Linear Terminal Guidance","Lateral & Longitudinal Autopilot State-Space Control","Real-Time Hardware-In-The-Loop (HIL) Validation","Anti-Jamming GPS/INS Tactical Inertial Filter Units","Actuator Dynamics & Jet Vane TVC Control Algorithms"]', '["MATLAB/Simulink","C/C++","ROS2","RTLinux","MIL-STD-1553","DSP Microcontrollers"]', 1, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT OR IGNORE INTO "Service" ("id", "slug", "title", "shortDescription", "fullDescription", "icon", "category", "features", "technologies", "isActive", "createdAt", "updatedAt") VALUES (7, 'modern-fighter-aircraft-technology', 'Modern Fighter Aircraft Technology', 'Next-generation fly-by-wire flight control laws, lateral/longitudinal autopilots, and integrated avionics suites.', 'We provide specialized R&D for fourth and fifth-generation combat aircraft platforms. Our engineering spans digital fly-by-wire (DFBW) flight control laws, multi-mode radar target fusion, head-up display symbology synthesis, and fault-tolerant redundant computing architectures compliant with the most stringent DO-178C Level-A safety standards.', 'defence-aerospace', 'Defence & Aerospace', '["Digital Fly-By-Wire (DFBW) Flight Control Laws","Carefree Maneuvering & Flight Envelope Protection Systems","Integrated Avionics Mission Computer Software","Sensor Fusion: Radar, IFF, EW, and Optical Trackers","DO-178C / DO-254 Aerospace Certification Compliance","Longitudinal & Lateral-Directional Robust Autopilot"]', '["Ada","C/C++","Simulink","ARINC 429","MIL-STD-1760","Real-Time Embedded Systems"]', 1, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT OR IGNORE INTO "Service" ("id", "slug", "title", "shortDescription", "fullDescription", "icon", "category", "features", "technologies", "isActive", "createdAt", "updatedAt") VALUES (8, 'cyber-security', 'Cyber Security', 'Zero-trust defense architecture, military-grade penetration testing, cryptographic hardware, and threat mitigation.', 'Our cybersecurity unit protects mission-critical military networks, industrial SCADA infrastructure, and enterprise data repositories from nation-state level cyber threats. We deliver comprehensive penetration testing, cryptographic audit of embedded firmware, SIEM implementation, and post-quantum cryptographic readiness.', 'ai-software', 'AI & Software', '["Red Team Offensive Operations & Zero-Day Research","Embedded Firmware Reverse Engineering & Binary Audit","SCADA / ICS Industrial Protocol Hardening","Post-Quantum Lattice-Based Cryptography","Zero-Trust Network Access (ZTNA) Architectures","Automated Real-Time AI Threat Hunting with eBPF"]', '["Kali Linux","Ghidra","Wireshark","eBPF","Rust","OpenSSL 3.0","Snort/Suricata"]', 1, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT OR IGNORE INTO "Service" ("id", "slug", "title", "shortDescription", "fullDescription", "icon", "category", "features", "technologies", "isActive", "createdAt", "updatedAt") VALUES (9, 'ai-for-mba', 'AI for MBA', 'Executive decision-support algorithms, automated financial modeling, market foresight, and business intelligence.', 'Designed for MBA leaders, corporate strategists, and enterprise management, our AI for MBA platforms bridge deep computational models with high-level corporate governance. We build automated executive reporting consoles, automated competitive intelligence scraping engines, and predictive Monte Carlo scenario simulators for strategic capital allocation.', 'innovation-research', 'Innovation & Research', '["Automated Financial Statement & Valuation Synthesis","Predictive Scenario Simulation & Risk Modeling","Executive KPI Command Centers & Visual Intelligence","Generative Market Research & Competitor Surveillance","Supply Chain Vulnerability Quantification","Strategic M&A Synergies Prediction Engine"]', '["Python","PowerBI","Tableau","LangChain","LlamaIndex","React","FastAPI"]', 1, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT OR IGNORE INTO "Service" ("id", "slug", "title", "shortDescription", "fullDescription", "icon", "category", "features", "technologies", "isActive", "createdAt", "updatedAt") VALUES (10, 'ai-robotics-industrial', 'AI & Robotics Industrial', 'High-stiffness five-bar mechanism robots, ROS2 kinematics/dynamics, singularity analysis, and smart manufacturing.', 'Drawing from Dr. Dadireddy Srinivasulu Reddy’s milestone project at CAIR DRDO, our industrial robotics line designs closed-loop Five-Bar Mechanisms offering exceptional structural stiffness with near-zero manipulator bending. We engineer inverse kinematic solvers, static torque estimators, and ROS2/MoveIt motion planning algorithms for ultra-fast material handling.', 'robotics-autonomous', 'Robotics & Autonomous', '["Five-Bar Parallel Mechanism Custom Robotic Architecture","Closed-Loop Kinematics, Dynamics & Singularity Boundary Analysis","Static & Dynamic Torque Estimation for Motor Optimization","ROS2 / Gazebo / MoveIt Complete Simulation Pipeline","Industrial PLC & Fieldbus Integration (EtherCAT, Profinet)","Sub-Millimeter Robotic Repeatability Under High Payload"]', '["ROS2","MoveIt","Gazebo","OpenCV","Python","C++","RViz","SolidWorks"]', 1, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT OR IGNORE INTO "Service" ("id", "slug", "title", "shortDescription", "fullDescription", "icon", "category", "features", "technologies", "isActive", "createdAt", "updatedAt") VALUES (11, 'drones-uavs', 'Drones & UAVs', 'Tactical autonomous unmanned aerial vehicles, swarm intelligence, GPS-denied navigation, and precision payloads.', 'Our Unmanned Aerial Vehicles are purpose-built for harsh operational conditions. Equipped with military autopilot hardware (PX4/ArduPilot), encrypted long-range radio telemetry, and onboard visual inertial odometry, our UAVs can navigate and execute reconnaissance missions even when satellite GPS signals are severely jammed or spoofed.', 'robotics-autonomous', 'Robotics & Autonomous', '["Distributed Swarm Intelligence & Coordinated Flight Loops","GPS-Denied Navigation via Visual-Inertial Odometry (VIO)","Encrypted Tactical Data Links (AES-256 MAVLink)","Gimbal-Stabilized Dual Optical & Thermal Imaging Payloads","Automatic Waypoint Flight with Dynamic Collision Avoidance","Long-Endurance Hybrid Battery/Turbine Powertrains"]', '["PX4","ArduPilot","ROS2","MAVLink","Jetson Orin","C++","Python"]', 1, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT OR IGNORE INTO "Service" ("id", "slug", "title", "shortDescription", "fullDescription", "icon", "category", "features", "technologies", "isActive", "createdAt", "updatedAt") VALUES (12, 'autonomous-systems', 'Autonomous Systems', 'Self-governing intelligent machines with multi-modal sensor fusion, dynamic path planning, and fail-safe autonomy.', 'We build autonomous control kernels that eliminate the need for human teleoperation in complex, hazardous settings. By synthesizing data from 3D LiDAR, radar, cameras, and IMUs using Extended Kalman Filters (EKF), our systems create coherent 3D voxel representations of the physical world and plan kinematically feasible trajectories in real-time.', 'robotics-autonomous', 'Robotics & Autonomous', '["Multi-Modal 3D LiDAR, Radar & Camera Sensor Fusion","Real-Time Trajectory Optimization & Obstacle Avoidance","Extended Kalman Filtering (EKF) & Factor Graph SLAM","Hierarchical Finite State Machine & Behavior Trees","Graceful Degradation & Redundant Fail-Safe Protocols","Edge Compute Optimization for Sub-5ms Decision Cycles"]', '["ROS2","C++","Python","Nav2","PCL (Point Cloud Library)","CUDA","Eigen"]', 1, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT OR IGNORE INTO "Service" ("id", "slug", "title", "shortDescription", "fullDescription", "icon", "category", "features", "technologies", "isActive", "createdAt", "updatedAt") VALUES (13, 'mobile-robots', 'Mobile Robots', 'Wheeled, tracked, and legged robotic platforms for tactical reconnaissance, perimeter patrol, and warehouse logistics.', 'Our Mobile Robotics division develops modular, high-torque robotic chassis designed for rough terrain operations. From autonomous warehouse tugs operating 24/7 to ruggedized patrol rovers equipped with pan-tilt-zoom cameras and acoustic gunfire locators, our mobile platforms handle harsh indoor and outdoor challenges.', 'robotics-autonomous', 'Robotics & Autonomous', '["All-Terrain Differential & Skid-Steer Rugged Drive Bases","Autonomous Indoor/Outdoor SLAM Navigation (Nav2)","Perimeter Security Patrol with Automated Return-To-Charge","High-Torque BLDC Hub Motors with Field-Oriented Control","Modular Payload Mounts for Cameras, Arms & Sensors","Fleet Coordination Management Software Integration"]', '["ROS2","Nav2","Gazebo","C++","Python","BLDC Motor Drivers","CANopen"]', 1, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT OR IGNORE INTO "Service" ("id", "slug", "title", "shortDescription", "fullDescription", "icon", "category", "features", "technologies", "isActive", "createdAt", "updatedAt") VALUES (14, 'self-driving-e-vehicles', 'Self Driving E-Vehicles', 'Autonomous driving software stacks, drive-by-wire conversion, ADAS features, and smart electric vehicle platforms.', 'We develop full-stack autonomous driving intelligence tailored for electric passenger vehicles, industrial campus shuttles, and military logistics carriers. Our technology includes drive-by-wire electronic throttle and steering integration, HD vector map generation, deep lane detection, and predictive pedestrian behavior modeling.', 'robotics-autonomous', 'Robotics & Autonomous', '["Drive-By-Wire Throttle, Brake & Steer Electronic Interface","High-Definition (HD) Vector Point-Cloud Map Generation","Level 3/4 Autonomy Perception & Path Planning Stacks","Automated Emergency Braking & Blind Spot ADAS Features","Real-Time CARLA Simulator Model-in-the-Loop Validation","Automotive CAN/Ethernet Protocol Compliant Interfaces"]', '["CARLA Simulator","ROS2","Autoware","TensorRT","C++","Python","CAN Bus"]', 1, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT OR IGNORE INTO "Service" ("id", "slug", "title", "shortDescription", "fullDescription", "icon", "category", "features", "technologies", "isActive", "createdAt", "updatedAt") VALUES (15, 'ai-in-defence-products', 'AI in Defence Products', 'AI-infused defense hardware and tactical situational awareness software tailored for active operational theaters.', 'Our AI in Defence Products program integrates advanced machine learning models directly into ruggedized military field gear. From tactical smart scopes providing ballistic windage compensation to automated radar track classification, we deliver superior decision advantage to armed forces commanders operating in intense, high-stress electronic environments.', 'defence-aerospace', 'Defence & Aerospace', '["Battlefield Common Operational Picture (COP) Software","Ballistic Trajectory & Precision Fire Control Systems","Electronic Counter-Countermeasures (ECCM) Intelligence","Tactical Voice & Acoustic Gunfire Localization Networks","MIL-STD-810H Shock, Thermal & Vibration Hardened Hardware","Encrypted Distributed Squad Radio Mesh Communication"]', '["Embedded Linux","Jetson Orin","C++","PyTorch","FPGA Hardware","MIL-STD-810H"]', 1, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT OR IGNORE INTO "Service" ("id", "slug", "title", "shortDescription", "fullDescription", "icon", "category", "features", "technologies", "isActive", "createdAt", "updatedAt") VALUES (16, 'ai-in-social-space', 'AI in Social & Space', 'Satellite imagery processing, space mission orbital telemetry, public health informatics, and societal AI solutions.', 'We apply cutting-edge artificial intelligence to humanity’s grandest scientific and civic challenges. In the space domain, we build onboard satellite hyperspectral image compression and automated orbital debris tracking systems. For societal impact, our models assist governmental bodies in crop yield forecasting, disaster evacuation routing, and water resource management.', 'innovation-research', 'Innovation & Research', '["Hyperspectral Satellite Earth Observation Deep Analytics","Orbital Debris Tracking & Collision Avoidance Trajectories","Automated Disaster Relief & Flood Hazard Evacuation Mapping","Agricultural Crop Health & Drought Predictive Analytics","Public Healthcare Resource Allocation Optimization","Onboard Low-Power Spacecraft Neural Edge Inference"]', '["Python","GDAL","Rasterio","PyTorch","QGIS","Sentinel APIs","PostGIS"]', 1, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT OR IGNORE INTO "Service" ("id", "slug", "title", "shortDescription", "fullDescription", "icon", "category", "features", "technologies", "isActive", "createdAt", "updatedAt") VALUES (17, 'ai-advanced-civil-products', 'AI for Advanced Civil Products', 'Smart city infrastructure, structural health acoustic sensors, adaptive traffic signals, and intelligent energy grids.', 'Our civil AI product suite equips modern metropolises and infrastructure developers with predictive intelligence. We deploy continuous structural health monitoring nodes on highway bridges and dams, optimize municipal traffic lights based on live camera density feeds, and manage microgrid renewable energy distribution to minimize municipal carbon footprints.', 'innovation-research', 'Innovation & Research', '["Continuous Structural Health & Micro-Vibration Analysis","Adaptive Intelligent Traffic Signal Orchestration","Smart Grid Municipal Electricity Load Balancing","Municipal Water Pipeline Acoustic Leak Detection","Digital Twin Building Information Modeling (BIM) Sync","Automated Environmental Air Quality Forecasting"]', '["IoT Mesh","Python","TensorFlow","Time-Series DB","OpenCV","MQTT","Three.js"]', 1, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT OR IGNORE INTO "Service" ("id", "slug", "title", "shortDescription", "fullDescription", "icon", "category", "features", "technologies", "isActive", "createdAt", "updatedAt") VALUES (18, 'advanced-defence-ai-products', 'Advanced Defence AI Products (Army/Airforce/Navy)', 'End-to-end combat AI engineering across land forces, naval surface/subsea vessels, and aerospace fighter wings.', 'Sri Srinivasa AI Robotics Pvt. Ltd. (SSAIR) delivers premier tri-services defense systems tailored for the Indian Army, Indian Air Force, and Indian Navy. Led by former DRDO CAIR scientist Dr. Dadireddy Srinivasulu Reddy (15+ years R&D, IISc alumnus), we design complete combat AI architectures—from autonomous naval patrol boats to next-gen air combat autopilots and rugged ground combat vehicles.', 'defence-aerospace', 'Defence & Aerospace', '["Army: Autonomous Combat UGV & Hardened Perimeter Defense","Air Force: AI Flight Autopilots, Jam-Resistant Swarm Drones & GNC","Navy: Autonomous Surface Vessels (USV) & Subsea Sonar Analytics","Unified Tri-Services C4ISR Tactical Decision Fusion","DRDO CAIR Heritage Quality Assurance & Rigorous Testing","100% Indigenous Atmanirbhar Bharat Design & Development"]', '["C/C++","ROS2","RTLinux","MIL-STD Standards","PyTorch","FPGA","Encrypted Radio"]', 1, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);

