-- Seed research articles and achievements
INSERT OR IGNORE INTO "NewsArticle" ("id", "title", "excerpt", "content", "category", "publishedAt", "createdAt", "updatedAt") VALUES (1, 'Autonomous 6-DOF & 5-Bar Industrial Robotic Manipulator for Defense Assembly', 'High-precision closed-loop impedance control architecture and kinematic trajectory planning system engineered for heavy payload assembly and munitions handling.', 'Inspired by foundational parallel mechanism kinematics researched at CAIR DRDO, this work establishes closed-form inverse kinematics, Jacobian conditioning indices for singularity avoidance, and 1,000 Hz EtherCAT impedance control.', 'Research', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT OR IGNORE INTO "NewsArticle" ("id", "title", "excerpt", "content", "category", "publishedAt", "createdAt", "updatedAt") VALUES (2, 'Real-Time Aerial Object Detection & Tracking in Cluttered Scenes Using YOLOv3/v8', 'High-speed edge computer vision framework optimized for low-altitude UAV tactical reconnaissance delivering robust multi-spectral target detection.', 'We benchmark INT8 and FP16 TensorRT quantized YOLO architectures running directly on airborne companion GPUs, sustaining sub-10ms per-frame tracking accuracy.', 'Research', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT OR IGNORE INTO "NewsArticle" ("id", "title", "excerpt", "content", "category", "publishedAt", "createdAt", "updatedAt") VALUES (3, 'Decentralized Swarm SLAM & Multi-Agent Tactical Mapping in GPS-Denied Zones', 'Robust multi-robot collaborative mapping architecture combining LiDAR-inertial odometry with peer-to-peer consensus algorithms.', 'Our LIO-SAM factor-graph architecture merges compressed 3D submaps across low-bandwidth mesh links, converging on a unified tactical map without centralized single points of failure.', 'Research', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT OR IGNORE INTO "NewsArticle" ("id", "title", "excerpt", "content", "category", "publishedAt", "createdAt", "updatedAt") VALUES (4, 'SSAIR Demonstrates Autonomous Defense Robotics at National DefTech Summit', 'Our research team successfully demonstrated the heavy-duty robotic manipulator alongside real-time edge vision pods to defense leadership and scientists.', 'At the National DefTech Summit, SSAIR showcased live real-time object recognition pods synchronized with autonomous trajectory actuation.', 'News', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT OR IGNORE INTO "NewsArticle" ("id", "title", "excerpt", "content", "category", "publishedAt", "createdAt", "updatedAt") VALUES (5, 'Strategic Joint R&D Partnership Initiated for Autonomous Aerial Surveillance', 'SSAIR signs a collaborative development pact with aerospace innovators to integrate low-latency edge-inference intelligence.', 'Together with Sri Saraswathi Artificial Intelligence and Robotics, SSAIR integrates modular airborne AI inference payloads and anti-jam telemetry systems.', 'News', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT OR IGNORE INTO "NewsArticle" ("id", "title", "excerpt", "content", "category", "publishedAt", "createdAt", "updatedAt") VALUES (6, 'DRDO Best Team Award Conferred to Scientific Leadership', 'Conferred the prestigious DRDO Best Team Award recognizing exceptional research contributions in real-time embedded robotic control and defense systems.', 'Founder & Director Dr. Dadireddy Srinivasulu Reddy received the DRDO Best Team Award during his 15+ year tenure as Scientist D at CAIR (DRDO Bengaluru).', 'Achievement', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
